'use strict';
// Assembles roadmap/build/map.json from the registered source records.
// Entries that cannot be assembled are dropped and logged; the exit code stays 0.
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..', '..');
const BUILD_DIR = path.join(ROOT, 'roadmap', 'build');
const MAP_OUT = path.join(BUILD_DIR, 'map.json');
const LOG_OUT = path.join(BUILD_DIR, 'generate.log');

const ID_MAX = 32;
const SECTION_WORDS = ['overview', 'summary', 'status', 'notes', 'verification',
  'architecture', 'introduction', 'background', 'appendix', 'details', 'misc'];

const notes = [];
function note(kind, msg) { notes.push(kind + ': ' + msg); }
function readJson(p) { return JSON.parse(fs.readFileSync(p, 'utf8')); }

function writeLog() {
  fs.mkdirSync(BUILD_DIR, { recursive: true });
  fs.writeFileSync(LOG_OUT, (notes.length ? notes.join('\n') : 'no notes') + '\n');
}

function splitRecord(file) {
  const raw = fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
  const m = raw.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  const meta = {};
  if (!m) return { meta: meta, body: raw };
  for (const line of m[1].split('\n')) {
    const kv = line.match(/^([A-Za-z_][A-Za-z0-9_]*):\s*(.*)$/);
    if (kv) meta[kv[1]] = kv[2].trim();
  }
  return { meta: meta, body: m[2] };
}

// first paragraph under "## <heading>"
function sectionText(body, heading) {
  const lines = body.split('\n');
  const want = heading.trim().toLowerCase();
  for (let i = 0; i < lines.length; i++) {
    const h = lines[i].match(/^##\s+(.*?)\s*$/);
    if (!h || h[1].trim().toLowerCase() !== want) continue;
    const out = [];
    for (let j = i + 1; j < lines.length; j++) {
      if (/^#{1,6}\s/.test(lines[j])) break;
      if (!lines[j].trim()) { if (out.length) break; else continue; }
      out.push(lines[j].trim());
    }
    return out.join(' ').trim();
  }
  return null;
}

const groupsCfg = readJson(path.join(ROOT, 'roadmap', 'groups.json'));

function knownCategory(c) {
  const v = String(c || '').trim().toLowerCase();
  return groupsCfg.groups.some(function (g) { return g.categories.indexOf(v) !== -1; });
}

function groupFor(c) {
  const v = String(c || '').trim().toLowerCase();
  for (const g of groupsCfg.groups) if (g.categories.indexOf(v) !== -1) return g.name;
  return groupsCfg.fallbackGroup;
}

function prefixesFor(group) {
  const g = group.toLowerCase();
  const out = [g];
  const amp = g.split(/\s*&\s*/)[0].trim();
  if (amp && out.indexOf(amp) === -1) out.push(amp);
  const first = g.split(/\s+/)[0];
  if (first && out.indexOf(first) === -1) out.push(first);
  return out.sort(function (a, b) { return b.length - a.length; });
}

function slug(label, group) {
  let s = String(label).toLowerCase().trim();
  for (const p of prefixesFor(group)) {
    if (s === p) break;
    if (s.indexOf(p + ' ') === 0) { s = s.slice(p.length + 1).trim(); break; }
  }
  s = s.replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  if (s.length > ID_MAX) s = s.slice(0, ID_MAX).replace(/-+$/, '');
  return s;
}

function weakName(label) {
  const t = label.trim();
  if (t.split(/\s+/).length < 3) return 'fewer than three words';
  if (/scope$/i.test(t)) return 'ends with "scope"';
  if (/^(phase\s*\d+|\d+)\b/i.test(t)) return 'starts with a bare number or a phase number';
  return null;
}

const sources = readJson(path.join(ROOT, 'roadmap', 'sources.json'));
const entries = [];
const byId = new Map();

for (const rec of sources.records) {
  const abs = path.join(ROOT, rec.path);
  if (!fs.existsSync(abs)) {
    note('DROP', rec.path + ' - registered record file does not exist');
    continue;
  }
  const parsed = splitRecord(abs);
  const declared = String(parsed.meta.entries || '').split(';').map(function (s) { return s.trim(); }).filter(Boolean);
  const group = groupFor(parsed.meta.category);
  if (!parsed.meta.category) {
    note('NOTE', rec.path + ' - no category declared; its entries fall back to "' + group + '"');
  } else if (!knownCategory(parsed.meta.category)) {
    note('NOTE', rec.path + ' - category "' + parsed.meta.category + '" is not listed in roadmap/groups.json; its entries fall back to "' + group + '"');
  }

  for (const reg of (rec.entries || [])) {
    const label = String(reg.label || '').trim();
    if (!label) { note('DROP', rec.path + ' - registration with an empty label'); continue; }
    if (declared.indexOf(label) === -1) {
      note('DROP', '"' + label + '" (' + rec.path + ') - registered in roadmap/sources.json but not declared in the record\'s front-matter "entries"; the two declarations must match exactly');
      continue;
    }
    const description = sectionText(parsed.body, label);
    if (!description) {
      note('DROP', '"' + label + '" (' + rec.path + ') - no "## ' + label + '" section with a plain-language description');
      continue;
    }
    const parts = label.split('>').map(function (s) { return s.trim(); }).filter(Boolean);
    const leaf = parts[parts.length - 1];
    const parentLabel = parts.length > 1 ? parts[parts.length - 2] : null;
    if (SECTION_WORDS.indexOf(leaf.toLowerCase()) !== -1) {
      note('DROP', '"' + label + '" (' + rec.path + ') - "' + leaf + '" is a structural section word, not the name of a capability');
      continue;
    }
    const id = slug(leaf, group);
    if (!id) { note('DROP', '"' + label + '" (' + rec.path + ') - reduces to an empty identifier'); continue; }
    const weak = weakName(leaf);
    if (weak) {
      note('WEAK', '"' + leaf + '" (' + rec.path + ') - ' + weak + '; admitted anyway, but this form reads ambiguously and collides easily');
    }
    if (byId.has(id)) {
      const other = byId.get(id);
      console.error('ERROR: duplicate entry id "' + id + '"');
      console.error('  "' + other.label + '" from ' + other.source);
      console.error('  "' + leaf + '" from ' + rec.path);
      console.error('  ids are derived from labels and truncated to ' + ID_MAX + ' characters');
      writeLog();
      process.exit(1);
    }
    const entry = {
      id: id,
      label: leaf,
      group: group,
      parent: parentLabel ? slug(parentLabel, group) : null,
      status: String(reg.status || parsed.meta.status || '').trim(),
      description: description,
      source: rec.path,
      paths: String(parsed.meta.paths || '').split(',').map(function (s) { return s.trim(); }).filter(Boolean)
    };
    byId.set(id, entry);
    entries.push(entry);
  }
}

for (const e of entries) {
  if (e.parent && !byId.has(e.parent)) {
    note('NOTE', '"' + e.label + '" (' + e.source + ') - parent entry "' + e.parent + '" was not assembled; emitted at top level instead');
    e.parent = null;
  }
}

fs.mkdirSync(BUILD_DIR, { recursive: true });
fs.writeFileSync(MAP_OUT, JSON.stringify({
  groups: groupsCfg.groups.map(function (g) { return g.name; }),
  entries: entries
}, null, 2) + '\n');
writeLog();
console.log('generated ' + entries.length + ' entries -> roadmap/build/map.json');
console.log(notes.length + ' note(s) -> roadmap/build/generate.log');

