'use strict';
// Rebuilds the data the map service serves. Does NOT re-run generation.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT = path.resolve(__dirname, '..', '..');
const MAP = path.join(ROOT, 'roadmap', 'build', 'map.json');
const OUT = path.join(ROOT, 'roadmap', 'build', 'served.json');
const SERVED_STATUSES = ['built', 'in-progress', 'planned'];

if (!fs.existsSync(MAP)) {
  console.error('ERROR: roadmap/build/map.json is missing - run generate.js first');
  process.exit(1);
}

const raw = fs.readFileSync(MAP, 'utf8');
const map = JSON.parse(raw);
const kept = [];
const withheld = [];

for (const e of map.entries) {
  if (SERVED_STATUSES.indexOf(e.status) === -1) {
    withheld.push(e.id + ' (status "' + e.status + '")');
    continue;
  }
  kept.push(e);
}

fs.writeFileSync(OUT, JSON.stringify({
  mapHash: crypto.createHash('sha1').update(raw).digest('hex').slice(0, 12),
  groups: map.groups,
  entries: kept
}, null, 2) + '\n');

console.log('service rebuilt: ' + kept.length + ' entries served, ' + withheld.length + ' withheld');
if (withheld.length) console.log('withheld: ' + withheld.join(', '));

