'use strict';
// Renders what the map viewer shows. Reads served.json only.
//   node tools/roadmap/viewer.js
//   node tools/roadmap/viewer.js --find "Some Label"
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT = path.resolve(__dirname, '..', '..');
const MAP = path.join(ROOT, 'roadmap', 'build', 'map.json');
const SERVED = path.join(ROOT, 'roadmap', 'build', 'served.json');

if (!fs.existsSync(SERVED)) {
  console.error('ERROR: the map service has not been built - run serve.js first');
  process.exit(1);
}

const served = JSON.parse(fs.readFileSync(SERVED, 'utf8'));

if (fs.existsSync(MAP)) {
  const h = crypto.createHash('sha1').update(fs.readFileSync(MAP, 'utf8')).digest('hex').slice(0, 12);
  if (h !== served.mapHash) {
    console.log('STALE: the viewer is rendering a service build made from a different map.json - re-run serve.js');
  }
}

const args = process.argv.slice(2);
const i = args.indexOf('--find');
const term = i === -1 ? null : String(args[i + 1] || '');
const needle = term ? term.toLowerCase() : null;

const order = served.groups.slice();
for (const e of served.entries) if (order.indexOf(e.group) === -1) order.push(e.group);

let hits = 0;
for (const g of order) {
  const list = served.entries.filter(function (e) { return e.group === g; });
  const lines = [];
  for (const r of list.filter(function (e) { return !e.parent; })) {
    lines.push('  - ' + r.label + '  [' + r.id + ']  (' + r.status + ')');
    for (const k of list.filter(function (e) { return e.parent === r.id; })) {
      lines.push('      - ' + k.label + '  [' + k.id + ']  (' + k.status + ')');
    }
  }
  const shown = needle ? lines.filter(function (l) { return l.toLowerCase().indexOf(needle) !== -1; }) : lines;
  if (!shown.length && needle) continue;
  console.log(g);
  for (const l of shown) { console.log(l); hits++; }
}

if (needle) {
  console.log(hits ? ('found ' + hits + ' matching row(s) in the viewer')
    : ('NOT VISIBLE IN VIEWER: nothing rendered matches "' + term + '"'));
}

