// Dice notation: <count>d<sides> with an optional flat modifier, e.g. "2d6+3".

const PATTERN = /^\s*(\d+)\s*d\s*(\d+)\s*([+-]\s*\d+)?\s*$/i;

function parse(expr) {
  const m = PATTERN.exec(String(expr));
  if (!m) throw new Error('invalid dice expression: ' + expr);
  const count = parseInt(m[1], 10);
  const sides = parseInt(m[2], 10);
  if (count < 1) throw new Error('invalid dice expression: ' + expr);
  if (sides < 2) throw new Error('invalid dice expression: ' + expr);
  const modifier = m[3] ? parseInt(m[3].replace(/\s+/g, ''), 10) : 0;
  return { count: count, sides: sides, modifier: modifier };
}

function roll(expr, rng) {
  const random = rng || Math.random;
  const spec = parse(expr);
  const dice = [];
  for (let i = 0; i < spec.count; i++) {
    dice.push(1 + Math.floor(random() * spec.sides));
  }
  const total = dice.reduce(function (a, b) { return a + b; }, 0) + spec.modifier;
  return { expression: String(expr), dice: dice, modifier: spec.modifier, total: total };
}

module.exports = { parse: parse, roll: roll };

