  return party.members.reduce(function (sum, m) { return sum + m.level * 12; }, 0);
}

function encounterWeight(encounter) {
  return encounter.foes.reduce(function (sum, f) { return sum + (f.challenge || 1) * 10 * (f.count || 1); }, 0);
}

function score(party, encounter) {
  const budget = partyBudget(party);
  if (budget <= 0) throw new Error('party has no members');
  const ratio = encounterWeight(encounter) / budget;
  const band = THRESHOLDS.find(function (t) { return ratio <= t.upTo; });
  return { ratio: Math.round(ratio * 100) / 100, verdict: band.verdict };
}

module.exports = { score: score, partyBudget: partyBudget, encounterWeight: encounterWeight };

