// Campaign events in dated order, plus the era boundaries they fall inside.

const ERAS = [
  { name: 'Founding', from: -400, to: 0 },
  { name: 'Long Quiet', from: 1, to: 320 },
  { name: 'Present Age', from: 321, to: 9999 }
];

function createTimeline() {
  return { events: [] };
}

function addEvent(timeline, event) {
  if (typeof event.year !== 'number') throw new Error('event needs a year');
  timeline.events.push({ year: event.year, title: event.title, secret: !!event.secret });
  timeline.events.sort(function (a, b) { return a.year - b.year; });
  return timeline;
}

function knownBy(timeline, year, includeSecret) {
  return timeline.events.filter(function (e) {
    return e.year <= year && (includeSecret || !e.secret);
  });
}

function eraOf(year) {
  const era = ERAS.find(function (e) { return year >= e.from && year <= e.to; });
  return era ? era.name : 'Unrecorded';
}

function eraSpans() {
  return ERAS.map(function (e) { return { name: e.name, from: e.from, to: e.to }; });
}

module.exports = {
  createTimeline: createTimeline,
  addEvent: addEvent,
  knownBy: knownBy,
  eraOf: eraOf,
  eraSpans: eraSpans
};

