'use strict';
// Character sheet: validation, derived stats, layout, rendering, autosave and print export.
// This module has grown to cover most of the sheet surface.

const fs = require('fs');
const path = require('path');

const ABILITIES = ['str', 'dex', 'con', 'int', 'wis', 'cha'];
const SAVE_DIR = path.join(__dirname, '..', '..', '.local', 'characters');

// --- validation -----------------------------------------------------------

function validate(character) {
  const problems = [];
  if (!character || typeof character !== 'object') return ['character is missing'];
  if (!character.name) problems.push('character has no name');
  if (!character.className) problems.push('character has no class');
  if (typeof character.level !== 'number' || character.level < 1) problems.push('level must be at least 1');
  for (const a of ABILITIES) {
    const v = character.abilities ? character.abilities[a] : undefined;
    if (typeof v !== 'number') problems.push('ability ' + a + ' is missing');
    else if (v < 1 || v > 30) problems.push('ability ' + a + ' out of range');
  }
  for (const item of character.equipment || []) {
    if (!item.name) problems.push('an equipment entry has no name');
  }
  return problems;
}

// --- derived stats --------------------------------------------------------

function modifier(value) {
  return Math.floor((value - 10) / 2);
}

function proficiencyBonus(level) {
  return 2 + Math.floor((level - 1) / 4);
}

function armourClass(character) {
  let ac = 10 + modifier(character.abilities.dex);
  for (const item of character.equipment || []) {
    if (item.armour) ac = item.armour + (item.allowsDex ? modifier(character.abilities.dex) : 0);
    if (item.shield) ac += 2;
  }
  return ac;
}

function initiative(character) {
  return modifier(character.abilities.dex);
}

function saves(character) {
  const out = {};
  const prof = proficiencyBonus(character.level);
  for (const a of ABILITIES) {
    out[a] = modifier(character.abilities[a]) + ((character.saveProficiencies || []).indexOf(a) !== -1 ? prof : 0);
  }
  return out;
}

// --- layout and rendering -------------------------------------------------

function blocks(character) {
  const s = saves(character);
  return [
    { title: 'Identity', rows: [character.name, character.className + ' ' + character.level] },
    { title: 'Abilities', rows: ABILITIES.map(function (a) { return a.toUpperCase() + ' ' + character.abilities[a] + ' (' + fmt(modifier(character.abilities[a])) + ')'; }) },
    { title: 'Defence', rows: ['AC ' + armourClass(character), 'Initiative ' + fmt(initiative(character))] },
    { title: 'Saves', rows: ABILITIES.map(function (a) { return a.toUpperCase() + ' ' + fmt(s[a]); }) },
    { title: 'Equipment', rows: (character.equipment || []).map(function (i) { return i.name; }) }
  ];
}

function fmt(n) {
  return n >= 0 ? '+' + n : String(n);
}

function render(character) {
  const problems = validate(character);
  if (problems.length) return 'cannot render sheet:\n  ' + problems.join('\n  ');
  return blocks(character).map(function (b) {
    return b.title + '\n' + b.rows.map(function (r) { return '  ' + r; }).join('\n');
  }).join('\n\n');
}

function renderForPrint(character) {
  return render(character).replace(/\n/g, '\r\n') + '\r\n\r\n-- printed sheet --\r\n';
}

// --- persistence ----------------------------------------------------------

function savePath(character) {
  return path.join(SAVE_DIR, String(character.name || 'unnamed').toLowerCase().replace(/[^a-z0-9]+/g, '-') + '.json');
}

function autosave(character) {
  fs.mkdirSync(SAVE_DIR, { recursive: true });
  fs.writeFileSync(savePath(character), JSON.stringify(character, null, 2));
  return savePath(character);
}

function load(name) {
  const p = savePath({ name: name });
  if (!fs.existsSync(p)) return null;
  return JSON.parse(fs.readFileSync(p, 'utf8'));
}

module.exports = {
  validate: validate,
  modifier: modifier,
  proficiencyBonus: proficiencyBonus,
  armourClass: armourClass,
  initiative: initiative,
  saves: saves,
  blocks: blocks,
  render: render,
  renderForPrint: renderForPrint,
  autosave: autosave,
  load: load
};

