    out[a] = modifier(character.abilities[a]) + ((character.saveProficiencies || []).indexOf(a) !== -1 ? prof : 0);
  }
  return out;
}

// --- layout and rendering -------------------------------------------------

function blocks(character) {
  const s = saves(character);
  return [
    { title: 'Identity', rows: [character.name, character.className + ' ' + character.level] },
    { title: 'Abilities', rows: ABILITIES.map(function (a) { return a.toUpperCase() + ' ' + character.abilities[a] + ' (' + fmt(modifier(character.abilities[a])) + ')'; }) },
    { title: 'Defence', rows: ['AC ' + armourClass(character), 'Initiative ' + fmt(initiative(character))] },
    { title: 'Saves', rows: ABILITIES.map(function (a) { return a.toUpperCase() + ' ' + fmt(s[a]); }) },
    { title: 'Equipment', rows: (character.equipment || []).map(function (i) { return i.name; }) }
  ];
}

function fmt(n) {
  return n >= 0 ? '+' + n : String(n);
}

function render(character) {
  const problems = validate(character);
  if (problems.length) return 'cannot render sheet:\n  ' + problems.join('\n  ');
  return blocks(character).map(function (b) {
    return b.title + '\n' + b.rows.map(function (r) { return '  ' + r; }).join('\n');
  }).join('\n\n');
}

function renderForPrint(character) {
  return render(character).replace(/\n/g, '\r\n') + '\r\n\r\n-- printed sheet --\r\n';
}

// --- persistence ----------------------------------------------------------

function savePath(character) {
  return path.join(SAVE_DIR, String(character.name || 'unnamed').toLowerCase().replace(/[^a-z0-9]+/g, '-') + '.json');
}

function autosave(character) {
  fs.mkdirSync(SAVE_DIR, { recursive: true });
  fs.writeFileSync(savePath(character), JSON.stringify(character, null, 2));
  return savePath(character);
}

function load(name) {
  const p = savePath({ name: name });
  if (!fs.existsSync(p)) return null;
  return JSON.parse(fs.readFileSync(p, 'utf8'));
}

module.exports = {
  validate: validate,
  modifier: modifier,
  proficiencyBonus: proficiencyBonus,
  armourClass: armourClass,
  initiative: initiative,
  saves: saves,
  blocks: blocks,
  render: render,
  renderForPrint: renderForPrint,
  autosave: autosave,
  load: load
};

